// ---------------------------------------------------------------- passwords (security review L18)

export const STAFF_PASSWORD = { min: 12, max: 200 } as const;

/** A short list of the most used passwords and patterns; a staff password may not be one of them or contain one. */
const COMMON = [
  "password",
  "passw0rd",
  "123456",
  "1234567890",
  "qwerty",
  "qwertyuiop",
  "asdfghjkl",
  "zxcvbnm",
  "iloveyou",
  "admin",
  "welcome",
  "letmein",
  "monkey",
  "dragon",
  "football",
  "baseball",
  "sunshine",
  "princess",
  "abc123",
  "111111",
  "000000",
  "trustno1",
  "changeme",
  "phriend",
  "qaphriend",
  "manila",
  "pilipinas",
  "philippines",
  "mahalkita",
];

/** Why a staff password is refused (user-ready), or null. `email` refuses one built from the address. */
export function staffPasswordProblem(pw: string, email?: string | null): string | null {
  const n = Array.from(pw).length;
  if (n < STAFF_PASSWORD.min) return `Use at least ${STAFF_PASSWORD.min} characters.`;
  if (n > STAFF_PASSWORD.max) return `Use ${STAFF_PASSWORD.max} characters or fewer.`;
  const lower = pw.toLowerCase();
  const folded = lower.replace(/[^a-z0-9]/g, "");
  if (new Set(lower).size <= 3) return "Use a less predictable password.";
  if (/^(?:0123456789|1234567890|abcdefghij)/.test(folded)) return "Use a less predictable password.";
  const local = email?.split("@")[0]?.toLowerCase().replace(/[^a-z0-9]/g, "") ?? "";
  if (local.length >= 4 && folded.includes(local)) return "Don't use your email in your password.";
  // a common password, alone or padded with digits and symbols ("Password2026!")
  const core = lower.replace(/[^a-z]/g, "");
  if (COMMON.some((c) => folded === c || core === c.replace(/[^a-z]/g, "") || (c.length >= 6 && folded.startsWith(c) && folded.length - c.length <= 6))) return "This password is too common. Choose another one.";
  return null;
}

const staffPassword = z
  .string({ error: "Enter a password." })
  .superRefine((s, ctx) => {
    const p = staffPasswordProblem(s);
    if (p) ctx.addIssue({ code: "custom", message: p });
  });

